{"content": "import ast, random, math

def encrypt(msg, P):
    l = [list(P[0]), list(P[1])]
    ct = []
    def nxt(i):
        l[i][3] = (l[i][3]*l[i][1] + l[i][2]) % l[i][0]
        return l[i][3]
    for ch in msg:
        for bit in list(map(int, list(f"{ch:07b}"))):
            ct.append(nxt(bit))
        for i in (0, 1):
            l[i] = [nxt(i) for _ in range(4)]
    return ct

def lcg_test(u):
    """k>=5 gives gcd of >=2 determinants -> real filter. k<5 unconstrained."""
    k = len(u)
    if k < 5:
        return True, None
    t = [u[i+1]-u[i] for i in range(k-1)]
    G = 0
    for j in range(1, k-2):
        G = math.gcd(G, abs(t[j+1]*t[j-1] - t[j]*t[j]))
    return G > max(u), G

def cands(blk):
    out = []
    for x in range(128):
        bits = [(x >> (6-j)) & 1 for j in range(7)]
        u0 = [v for b, v in zip(bits, blk) if b == 0]
        u1 = [v for b, v in zip(bits, blk) if b == 1]
        if lcg_test(u0)[0] and lcg_test(u1)[0]:
            out.append(x)
    return out

rng = random.Random(11)
def rp():
    return tuple(rng.getrandbits(128) for _ in range(4))
msg = b"0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRST"
assert len(msg) == 52 and max(msg) < 128
ct_s = encrypt(msg, (rp(), rp()))
print("selftest len", len(ct_s), "==7*52?", len(ct_s) == 7*52)
good = 0; counts = []
for i in range(52):
    cs = cands(ct_s[7*i:7*i+7]); counts.append(len(cs)); good += (msg[i] in cs)
print("selftest true accepted", good, "/52; counts", counts)

